<?php declare(strict_types=1); namespace Modules\Users\Requests; use Core\Http\FormRequest; use Core\Http\Request; class UpdateUserRequest extends FormRequest { public function rules(): array { $id = $this->userId ?? null; return [ 'name' => 'required|string|max:100', 'email' => 'required|email|unique:users,email,' . $id, 'password' => 'nullable|string|min:8|confirmed', 'phone' => 'nullable|string|max:50', 'locale' => 'nullable|string|max:10', 'status' => 'required|in:active,inactive', 'roles' => 'nullable|array', ]; } public int|string|null $userId = null; public function forUser(int|string $id): static { $this->userId = $id; return $this; } public function authorize(Request $request): bool { return auth()->userCan('users.manage'); } } 